def create_business_lines(apps, schema_editor):
    BusinessLine = apps.get_model('accounts', 'BusinessLine')
    for business_line in NEW_BUSINESS_LINE_CHOICES:
        BusinessLine.objects.create(
            slug=business_line[0],
            name_fr=business_line[1],
            name_en=business_line[2],
        )


def affect_structure_business_line(apps, schema_editor):
    BusinessLine = apps.get_model('accounts', 'BusinessLine')
    Structure = apps.get_model('accounts', 'Structure')
    for business_line in BUSINESS_LINE_CHOICES:
        new_business_line = BusinessLine.objects.filter(slug=NEW_BUSINESS_LINE_CHOICES[business_line[2]][0]).first()
        Structure.objects.filter(business_line=business_line[0]).update(new_business_line=new_business_line)
    if Structure.objects.filter(business_line=None).exists():
        print("These structures don't have business line ", Structure.objects.filter(business_line=None).values_list("pk", flat=True))


def affect_structure_secondary_business_lines(apps, schema_editor):
    BusinessLine = apps.get_model('accounts', 'BusinessLine')
    Structure = apps.get_model('accounts', 'Structure')
    for business_line in BUSINESS_LINE_CHOICES:
        new_business_line = BusinessLine.objects.filter(slug=NEW_BUSINESS_LINE_CHOICES[business_line[2]][0]).first()
        for structure in Structure.objects.filter(secondary_business_lines__contains=business_line[0]):
            structure.new_secondary_business_lines.add(new_business_line)


def affect_user_business_line(apps, schema_editor):
    BusinessLine = apps.get_model('accounts', 'BusinessLine')
